INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(41200, 0, 0, '$n has captured a Colossal Viseclaw!', 16, 0, 100.0, 0, 0, 34494, 0, 0, ''),
(41200, 3, 0, 'Ku-Yao\'s bedroll is empty. He\'s not here.', 42, 0, 100.0, 0, 0, 0, 0, 0, ''),
(54020, 3, 0, 'A dark force from within the Dragon Soul reacts violently to the cleansing!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(55370, 0, 0, 'The portal worked and we are still in one piece. Good! I was worried we might overload the network by adding another beacon.', 12, 0, 100.0, 0, 0, 78232, 0, 0, ''),
(56439, 0, 0, 'Die or surrender. You cannot defeat me.', 14, 0, 100.0, 0, 0, 29633, 0, 0, ''),
(56439, 1, 0, 'You cannot escape me. I am... in... every...  breath...', 14, 0, 100.0, 0, 0, 29634, 0, 0, ''),
(56439, 2, 0, 'See how effortlessly you become unraveled.', 14, 0, 100.0, 0, 0, 29635, 0, 0, ''),
(56439, 3, 0, 'Succumb to the darkness inside your soul.', 14, 0, 100.0, 0, 0, 29636, 0, 0, ''),
(56439, 4, 0, 'All is lost.', 14, 0, 100.0, 0, 0, 29637, 0, 0, ''),
(56439, 5, 0, 'Abandon all hope.', 14, 0, 100.0, 0, 0, 29638, 0, 0, ''),
(56439, 6, 0, 'Embrace your despair.', 14, 0, 100.0, 0, 0, 29639, 0, 0, ''),
(56448, 0, 0, 'The waters whisper to me... enemies approach.', 12, 0, 100.0, 0, 0, 28265, 0, 0, ''),
(56448, 1, 0, 'You dare to disturb these waters? You will drown!', 12, 0, 100.0, 0, 0, 28257, 0, 0, ''),
(56448, 2, 0, 'The water reacts violently to your touch!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(56448, 3, 0, 'Living water, bring them death!', 12, 0, 33.0, 0, 0, 28261, 0, 0, ''),
(56448, 3, 1, 'Spring to life!', 12, 0, 100.0, 0, 0, 28259, 0, 0, ''),
(56448, 4, 0, 'Behold the power of torrential waters!', 12, 0, 100.0, 0, 0, 28266, 0, 0, ''),
(56448, 5, 0, 'The darkness clears...', 12, 0, 100.0, 0, 0, 28262, 0, 0, ''),
(56448, 5, 1, 'I peer into these waters and my reflection is empty...', 12, 0, 100.0, 0, 0, 28263, 0, 0, ''),
(56448, 5, 2, 'Waters... claim me...', 12, 0, 100.0, 0, 0, 28264, 0, 0, ''),
(56448, 6, 0, 'Your cause is hopeless.', 12, 0, 100.0, 0, 0, 28268, 0, 0, ''),
(56448, 6, 1, 'As the waters foretold.', 12, 0, 100.0, 0, 0, 28267, 0, 0, ''),
(56732, 0, 0, 'The heart of the Great Serpent will not fall into your hands!', 14, 0, 100.0, 0, 0, 27603, 0, 0, ''),
(56732, 1, 0, 'The haze has been lifted from my eyes... forgive me for doubting you...', 14, 0, 100.0, 0, 0, 27604, 0, 0, ''),
(56732, 2, 0, 'Jade Serpent, grant me strength!', 14, 0, 100.0, 0, 0, 27605, 0, 0, ''),
(56732, 3, 0, 'The cycle must continue, the Jade Serpent must be reborn!', 14, 0, 100.0, 0, 0, 27606, 0, 0, ''),
(56732, 4, 0, 'Your forces are weak!', 14, 0, 100.0, 0, 0, 27607, 0, 0, ''),
(56732, 5, 0, 'The heart is MINE!', 14, 0, 100.0, 0, 0, 27608, 0, 0, ''),
(56732, 6, 0, 'Leave this place.', 14, 0, 100.0, 0, 0, 27609, 0, 0, ''),
(56762, 0, 0, 'Be free of doubt, priestess...', 14, 0, 100.0, 0, 0, 28559, 0, 0, ''),
(56843, 0, 0, 'You there! In the rafters! My sacred library has become possessed by the Sha!', 14, 0, 100.0, 0, 0, 30887, 0, 0, ''),
(56843, 1, 0, 'See how they pour from every letter of these sacred scrolls... corrupting them! Defiling them!', 14, 0, 100.0, 0, 0, 30888, 0, 0, ''),
(56843, 2, 0, 'I beseech you, kind strangers. Cleanse this place of their foul presence! Lay our stories to rest!', 14, 0, 100.0, 0, 0, 30889, 0, 0, ''),
(56843, 3, 0, 'You must destroy the source of the corruption! Quickly, before our cherished history is erased forever!', 14, 0, 100.0, 0, 0, 30890, 0, 0, ''),
(56843, 4, 0, 'Oh, my. If I am not mistaken, it appears that the tale of Zao Sunseeker has come to life before us.', 14, 0, 100.0, 0, 0, 30901, 0, 0, ''),
(56843, 5, 0, 'According to the legend, long ago, there were five suns that burned brightly in the sky. When the winds blew, their intense heat caused great wildfires.', 14, 0, 100.0, 0, 0, 30902, 0, 0, ''),
(56843, 6, 0, 'Crops wilted, villages burned, and families wandered endlessly to seek refuge from the flames...', 14, 0, 100.0, 0, 0, 30903, 0, 0, ''),
(56843, 7, 0, 'I can allow this no longer!', 14, 0, 100.0, 0, 0, 27747, 0, 0, ''),
(56843, 8, 0, 'The fires, they are burning the library! Please, heroes! Purge this evil before the temple crumbles to ash!', 14, 0, 100.0, 0, 0, 30904, 0, 0, ''),
(56843, 9, 0, 'Zao has become corrupted too! Please, fight him with dignity...', 14, 0, 100.0, 0, 0, 30906, 0, 0, ''),
(56843, 10, 0, 'Ah, it is not yet over. From what I see, we face the trial of the yaungol. Let me shed some light...', 14, 0, 100.0, 0, 0, 30896, 0, 0, ''),
(56843, 11, 0, 'As the tale goes, the yaungol was traveling across the Kun\'lai plains when suddenly he was ambushed by two strange creatures!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(56843, 12, 0, 'The yaungol attacked the beasts with great determination and ferocity. Yet, the more he attacked, the more fearsome the beasts grew!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(56843, 13, 0, 'However, when he let it alone, the beast shrank to near nothingness.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(56843, 14, 0, 'For you see, strife feeds on conflict. When you have peace in your heart, strife will find somewhere else to roam.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(56843, 15, 0, 'For you see, strife feeds on conflict. When you have peace in your heart, strife will find somewhere else to roam.', 14, 0, 100.0, 1, 0, 30900, 0, 0, ''),
(56843, 16, 0, 'You have my thanks, heroes. You have given peace to this sacred temple.', 14, 0, 100.0, 1, 0, 30885, 0, 0, ''),
(56843, 17, 0, 'Now, off with you! I require meditation before I begin the restoration ritual.', 14, 0, 100.0, 1, 0, 30886, 0, 0, ''),
(56843, 18, 0, 'Zao was a true champion of our people, how sad it is to see his story tainted by the sha. I am relieved to see justice served to his memory.', 14, 0, 100.0, 1, 0, 30907, 0, 0, ''),
(56872, 0, 0, 'FOR THE ANCIENTS!', 14, 0, 100.0, 0, 0, 33369, 0, 0, ''),
(58826, 0, 0, 'The blistering heat must have dulled my senses... mirages! All of you!', 14, 0, 100.0, 0, 0, 27748, 0, 0, ''),
(58826, 1, 0, 'I can allow this no longer!', 14, 0, 100.0, 0, 0, 27747, 0, 0, ''),
(59546, 0, 0, '\'Tis hard to decipher his true wish...', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(59546, 1, 0, 'He often seeks a lordly dish...', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(59546, 2, 0, 'To serve upon his table.', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(59546, 3, 0, 'When man asks favor of a fish...', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(59915, 0, 0, '%s is about to Overload!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 0, 0, 'Tender your souls, mortals! These are the halls of the dead!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 1, 0, 'Oh great spirit! Grant me the power of the earth!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 2, 0, '%s begins to channel a violent |cFFFF0404|Hspell:116040|h[Epicenter]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 3, 0, 'Oh exalted one! Through me you shall melt flesh from bone!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 4, 0, 'You have been affected by |cFFFF0404|Hspell:116784|h[Wildfire Spark]|h|r !', 42, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 5, 0, 'Oh sage of the ages! Instill to me your arcane wisdom!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60009, 6, 0, 'If they only knew... what horrors await...', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60043, 0, 0, '%s is about to Overload!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60043, 1, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_03.blp:20|t |c0093F8D1%s|r begins to petrify all players!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60047, 4, 0, '%s is about to Overload!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60051, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_04.blp:20|t |c0091D0F8%s|r begins to petrify all players!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60051, 1, 0, '%s is about to Overload!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60143, 0, 0, 'A pair of Zandalari Trolls burst through the doors ahead of you!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60143, 1, 0, 'No matter! We don\'t be needin\' what\'s back dat way anyhow!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60143, 2, 0, 'Now you done made me angry!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(60143, 3, 0, 'Fine, den! Time ta play, friends.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
