(73330, 11, 0, 'Yes!  Rook Stonetoe!  You remember me!  What has happened to you?', 14, 0, 100.0, 5, 0, 38133, 0, 0, ''),
(73330, 12, 0, 'I see. This sha energy has trapped their spirits here, to endlessly relive their failure. It feeds on their despair.', 14, 0, 100.0, 1, 0, 38134, 0, 0, ''),
(73330, 13, 0, 'This is a fate far worse than death - please, heroes!  Set their souls free!', 14, 0, 100.0, 1, 0, 38135, 0, 0, ''),
(73330, 14, 0, 'Rest in peace.', 14, 0, 100.0, 1, 0, 38136, 0, 0, ''),
(73330, 15, 0, 'May your souls become one with the land you gave your life to protect.', 14, 0, 100.0, 1, 0, 38137, 0, 0, ''),
(73342, 0, 0, 'The waters have not been cleansed!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73342, 1, 0, 'You must protect me.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73342, 2, 0, 'It falls to you to defend your master.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73349, 0, 0, 'We must defend the pools from their corruption!', 14, 0, 100.0, 1, 0, 0, 0, 0, ''),
(73483, 0, 0, 'It is not too late, Garrosh. Lay down the mantle of Warchief. We can end this here, now, with no more bloodshed.', 14, 0, 100.0, 0, 0, 38934, 0, 0, ''),
(73483, 3, 0, 'Never powerless Garrosh. And never alone.', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73493, 3, 0, 'Blue wire with the green stripe, or black wire with the yellow stripe? I can never remember.', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73494, 3, 0, 'Wait for me!', 12, 0, 100.0, 4, 0, 0, 0, 0, ''),
(73495, 3, 0, 'Blue wire with the green stripe, or black wire with the yellow stripe? I can never remember.', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73550, 3, 0, 'Steady hands..', 12, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73551, 0, 0, 'Wait for me!', 12, 0, 100.0, 4, 0, 38391, 0, 0, ''),
(73551, 3, 0, 'Wait for me!', 12, 0, 100.0, 4, 0, 0, 0, 0, ''),
(73553, 3, 0, 'Wait for me!', 12, 0, 100.0, 4, 0, 0, 0, 0, ''),
(73565, 0, 0, 'The door barring the South Tower has been breached!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73598, 3, 0, 'Это уже не новость, лорд. Пока мы с вами беседуем, флот короля Ринна уже подходит к Оргриммару.', 12, 0, 100.0, 5, 0, 0, 0, 0, ''),
(73605, 3, 0, 'It is always a pleasure to see you, Lady Proudmoore.', 12, 0, 100.0, 1, 0, 38161, 0, 0, ''),
(73628, 0, 0, 'The door barring the North Tower has been breached!', 41, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73709, 0, 0, 'Garrosh be concealin\' a whole hidden base. Where did his lust for power take him?', 14, 0, 100.0, 5, 0, 39146, 0, 0, ''),
(73709, 3, 0, 'People be dyin\' up above. Da city is in chaos. I\'m gonna finish it - stop da bloodshed. I\'ll come back for ya.', 14, 0, 100.0, 1, 0, 0, 0, 0, ''),
(73710, 3, 0, 'What should we do next?', 14, 0, 100.0, 6, 0, 0, 0, 0, ''),
(73714, 3, 0, 'I\'ll offer what aid I can, $n. Just promise you\'ll make lots of delicious Kor\'kron corpses on your way to Garrosh.', 12, 0, 100.0, 1, 0, 0, 0, 0, ''),
(73715, 3, 0, 'I\'ve got the brains, you\'ve got the muscle. Together, we\'ll make beautiful carnage.', 12, 0, 100.0, 396, 0, 0, 0, 0, ''),
(73775, 0, 0, 'Iron Sentinels! To me!', 14, 1, 100.0, 0, 0, 0, 0, 0, ''),
(73855, 0, 0, 'Send in da reserves! Charge!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73909, 0, 0, 'I\'m summoning a Flamestrike, lead them into it!', 14, 0, 10.0, 0, 0, 38152, 0, 0, ''),
(73939, 3, 0, 'What? Kor\'kron, to the gates! Now!', 14, 0, 100.0, 397, 0, 0, 0, 0, ''),
(73941, 0, 0, 'Our casualties are too heavy!', 14, 0, 100.0, 0, 0, 0, 0, 0, ''),
(73941, 3, 0, 'Perhaps our newfound reinforcements will aid us.', 12, 0, 100.0, 1, 0, 0, 0, 0, ''),
(73942, 3, 0, 'Da beast be slain!', 14, 0, 100.0, 5, 0, 39145, 0, 0, ''),
